$ErrorActionPreference='Stop'
$a='D:\Datos\the-eriksson-programme\autonomia\evidencia-318\production-b-source-audit';$e='D:\Datos\the-eriksson-programme\autonomia\evidencia-318';$repo='C:\Trabajo\the-eriksson-programme\cutoff306-20261113';$u=[Text.UTF8Encoding]::new($false)
function Put($n,$v){[IO.File]::WriteAllText((Join-Path $a $n),($v|ConvertTo-Json -Depth 12)+"`n",$u)}
$prior=Get-Content -LiteralPath ($a+'\prior318A-MANIFEST.json') -Raw|ConvertFrom-Json;$oldchecks=@();foreach($r in $prior.files){$f=Join-Path ($e+'\production-a-source-audit') $r.path;$oldchecks+=[ordered]@{path=$r.path;matches=((Get-Item -LiteralPath $f).Length -eq $r.bytes -and (Get-FileHash -LiteralPath $f).Hash.ToLowerInvariant() -ceq $r.raw_sha256)}}
$arch=$repo+'\papers\marginal-transfer\evidence318\document-audit318A';$original=$e+'\document-audit318A';$preserve=@();foreach($f in Get-ChildItem -LiteralPath $arch -Recurse -File){$rel=[IO.Path]::GetRelativePath($arch,$f.FullName);$orig=Join-Path $original $rel;$preserve+=[ordered]@{path=$rel;original_exists=(Test-Path -LiteralPath $orig);bytes=$f.Length;raw_sha256=(Get-FileHash -LiteralPath $f.FullName).Hash.ToLowerInvariant();original_equal=((Test-Path -LiteralPath $orig) -and (Get-Item -LiteralPath $orig).Length -eq $f.Length -and (Get-FileHash -LiteralPath $orig).Hash -ceq (Get-FileHash -LiteralPath $f.FullName).Hash)}}
$docman=Get-Content -LiteralPath ($arch+'\output-manifest.json') -Raw|ConvertFrom-Json;$docchecks=@();foreach($r in $docman.files){$f=Join-Path $arch $r.path;$docchecks+=[ordered]@{path=$r.path;matches=((Get-Item -LiteralPath $f).Length -eq $r.bytes -and (Get-FileHash -LiteralPath $f).Hash.ToLowerInvariant() -ceq $r.raw_sha256)}}
Put 'preservation-verification.json' ([ordered]@{prior_engineering_manifest_members=$oldchecks.Count;all_prior_engineering_unchanged=(@($oldchecks|Where-Object{-not $_.matches}).Count -eq 0);prior_engineering=$oldchecks;archived_failed_document_packet_files=$preserve.Count;all_archived_equal_original=(@($preserve|Where-Object{-not $_.original_equal}).Count -eq 0);archived_document=$preserve;document_manifest_members=$docchecks.Count;all_document_manifest_members_match=(@($docchecks|Where-Object{-not $_.matches}).Count -eq 0);document_manifest=$docchecks})
$v=Get-Content -LiteralPath ($a+'\source-input-verification.json') -Raw|ConvertFrom-Json;$lookup=@{};foreach($r in $v.files){$lookup[$r.path]=$r};$zip=[IO.Compression.ZipFile]::OpenRead($a+'\source-input-capture.zip');$checks=@();try{foreach($entry in $zip.Entries){$r=$lookup[$entry.FullName];$s=$entry.Open();try{$hash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($s)).ToLowerInvariant()}finally{$s.Dispose()};$checkout=Join-Path ($repo+'\papers\marginal-transfer') $entry.FullName;$checks+=[ordered]@{path=$entry.FullName;zip_matches=($null -ne $r -and $entry.Length -eq $r.bytes -and $hash -ceq $r.raw_sha256);checkout_matches=((Get-Item -LiteralPath $checkout).Length -eq $r.bytes -and (Get-FileHash -LiteralPath $checkout).Hash.ToLowerInvariant() -ceq $r.raw_sha256)}}}finally{$zip.Dispose()}
Put 'final-input-recheck.json' ([ordered]@{count=$checks.Count;all_zip_match=(@($checks|Where-Object{-not $_.zip_matches}).Count -eq 0);all_checkout_match=(@($checks|Where-Object{-not $_.checkout_matches}).Count -eq 0);files=$checks})
[ordered]@{engineering=$oldchecks.Count;engineering_ok=(@($oldchecks|Where-Object{-not $_.matches}).Count -eq 0);document=$preserve.Count;document_ok=(@($preserve|Where-Object{-not $_.original_equal}).Count -eq 0);document_manifest=$docchecks.Count;document_manifest_ok=(@($docchecks|Where-Object{-not $_.matches}).Count -eq 0);inputs=$checks.Count;zip_and_checkout_ok=(@($checks|Where-Object{-not $_.zip_matches -or -not $_.checkout_matches}).Count -eq 0)}|ConvertTo-Json